Django (this tree) only does attribute get/set/del on Local instances in
sync code paths, where asgiref's semantics reduce to thread-local storage.
"""
import threading


class Local:
    def __init__(self, thread_critical=False):
        super().__setattr__("_thread_critical", thread_critical)
        super().__setattr__("_tls", threading.local())

    def _dict(self):
        d = getattr(self._tls, "value", None)
        if d is None:
            d = {}
            self._tls.value = d
        return d

    def __getattr__(self, name):
        d = self._dict()
        if name in d:
            return d[name]
        raise AttributeError(name)

    def __setattr__(self, name, value):
        if name in ("_thread_critical", "_tls"):
            super().__setattr__(name, value)
            return
        self._dict()[name] = value

    def __delattr__(self, name):
        d = self._dict()
        if name in d:
            del d[name]
        else:
            raise AttributeError(name)

